  ('ga-012', 'Atlanta-Fulton Public Library Central Library', 'Public Library', 'library', 'Atlanta', 'GA', 'indoor', 'free', 0, 99, 1.5, 4.3, '["story time", "children''s room", "free"]', 'Central branch with regular preschool story times.'),
  ('ga-013', 'Callaway Gardens', 'Resort Gardens', 'park', 'Pine Mountain', 'GA', 'outdoor', '$$', 0, 99, 5.0, 4.6, '["butterfly center", "beach", "bike trails"]', 'Butterfly conservatory, bike trails and a freshwater beach.'),
  ('ga-014', 'Tellus Science Museum', 'Science Museum', 'museum', 'Cartersville', 'GA', 'indoor', '$$', 3, 99, 3.0, 4.7, '["fossils", "minerals", "planetarium"]', 'Mineral gallery, dinosaurs, a planetarium and a fossil dig.'),
  ('ga-015', 'Amicalola Falls State Park', 'State Park', 'park', 'Dawsonville', 'GA', 'outdoor', '$', 5, 99, 3.5, 4.8, '["waterfall", "stairs", "overlook"]', 'Tallest cascading waterfall in Georgia, with stair overlooks.'),
  ('il-001', 'Shedd Aquarium', 'Aquarium', 'aquarium', 'Chicago', 'IL', 'indoor', '$$$', 1, 99, 3.5, 4.7, '["belugas", "caribbean reef", "otters"]', 'Lakefront aquarium with belugas and a Caribbean reef tank.'),
  ('il-002', 'Field Museum', 'Natural History Museum', 'museum', 'Chicago', 'IL', 'indoor', '$$$', 3, 99, 4.0, 4.8, '["sue the t rex", "egypt", "dinosaurs"]', 'Home of SUE the T. rex and a walk-through Egyptian tomb.'),
  ('il-003', 'Museum of Science and Industry', 'Science Center', 'museum', 'Chicago', 'IL', 'indoor', '$$$', 3, 99, 4.5, 4.8, '["submarine", "coal mine", "idea factory"]', 'U-505 submarine, a coal mine ride and a toddler Idea Factory.'),
  ('il-004', 'Lincoln Park Zoo', 'Zoo', 'zoo', 'Chicago', 'IL', 'outdoor', 'free', 0, 99, 3.0, 4.7, '["free admission", "farm", "gorillas"]', 'Free year-round city zoo with a working farm for kids.'),
  ('il-005', 'Adler Planetarium', 'Planetarium', 'museum', 'Chicago', 'IL', 'indoor', '$$', 4, 99, 2.5, 4.6, '["space", "sky shows", "skyline views"]', 'Sky shows and space history with the best skyline view in town.'),
  ('il-006', 'Millennium Park', 'Urban Park', 'park', 'Chicago', 'IL', 'outdoor', 'free', 0, 99, 2.0, 4.8, '["the bean", "crown fountain", "splash"]', 'The Bean, plus the Crown Fountain kids can wade through.'),
  ('il-007', 'Chicago Children''s Museum', 'Children''s Museum', 'museum', 'Chicago', 'IL', 'indoor', '$$', 0, 10, 3.0, 4.5, '["water works", "dinosaur dig", "climbing"]', 'Navy Pier museum with a water works and a dinosaur dig pit.'),
  ('il-008', 'Brookfield Zoo', 'Zoo', 'zoo', 'Brookfield', 'IL', 'outdoor', '$$', 1, 99, 5.0, 4.7, '["dolphins", "hamill family play zoo", "carousel"]', 'Large suburban zoo with a play zoo built for young children.'),
  ('il-009', 'Chicago Botanic Garden', 'Botanical Garden', 'park', 'Glencoe', 'IL', 'outdoor', '$', 0, 99, 3.0, 4.8, '["islands", "model railroad", "kids garden"]', 'Twenty-seven gardens across nine islands, plus a train garden.'),
