INSERT INTO global_patterns (pattern_id, cluster_name, top_destinations, seasonal_preferences, notes) VALUES
  (1, 'Toddler-first city breaks', '["San Francisco, CA", "Tampa, FL", "Columbus, OH", "Sacramento, CA"]', '{"spring": "high", "summer": "medium", "fall": "high", "winter": "medium"}', 'Short days, indoor backups, splash pads and free parks. Families with a child under 5.'),
  (2, 'Science and space seekers', '["Houston, TX", "Merritt Island, FL", "Chicago, IL", "Flagstaff, AZ"]', '{"spring": "high", "summer": "high", "fall": "medium", "winter": "medium"}', 'Museum-heavy itineraries, timed-entry tickets, ages 8 and up.'),
  (3, 'National park road trippers', '["Grand Canyon Village, AZ", "Terlingua, TX", "Yosemite Valley, CA", "Logan, OH"]', '{"spring": "high", "summer": "medium", "fall": "high", "winter": "low"}', 'Multi-day drives, shoulder-season travel, stargazing and easy loop trails.'),
  (4, 'Budget weekend explorers', '["Chicago, IL", "Savannah, GA", "Phoenix, AZ", "Brecksville, OH"]', '{"spring": "high", "summer": "medium", "fall": "high", "winter": "medium"}', 'Free-admission zoos, libraries and public parks. Budget range $ dominates.'),
  (5, 'Aquarium and marine life fans', '["Atlanta, GA", "Monterey, CA", "Chicago, IL", "Clearwater, FL"]', '{"spring": "medium", "summer": "high", "fall": "medium", "winter": "high"}', 'Indoor-first planning; winter travel is common because weather does not matter.');
