  (9, 5, 'Grand Canyon, AZ', '2025-10-10', '2025-10-13', '{"days": [{"day": 1, "activities": [{"activity_id": "az-001", "name": "Grand Canyon National Park"}], "note": "Rim Trail plus the free shuttle."}, {"day": 2, "activities": [{"activity_id": "az-013", "name": "Petrified Forest National Park"}], "note": "Long drive, worth one day."}, {"day": 3, "activities": [{"activity_id": "az-014", "name": "Lowell Observatory"}], "note": "Night viewing in Flagstaff."}]}'),
