  (18, 10, 'Big Bend, TX', '2025-11-07', '2025-11-11', '{"days": [{"day": 1, "activities": [{"activity_id": "tx-012", "name": "Big Bend National Park"}], "note": "Santa Elena Canyon trail."}, {"day": 2, "activities": [{"activity_id": "tx-012", "name": "Big Bend National Park"}], "note": "Stargazing night; brought binoculars."}, {"day": 3, "activities": [{"activity_id": "tx-013", "name": "Austin Central Library"}], "note": "Rooftop stop on the drive back."}]}'),
