  (20, 12, 'Rochester, NY', '2025-12-27', '2025-12-29', '{"days": [{"day": 1, "activities": [{"activity_id": "ny-008", "name": "The Strong National Museum of Play"}], "note": "Full day; came back the next morning."}, {"day": 2, "activities": [{"activity_id": "ny-008", "name": "The Strong National Museum of Play"}], "note": "Butterfly garden was the quiet spot."}, {"day": 3, "activities": [{"activity_id": "ny-010", "name": "Buffalo Zoo"}], "note": "Short winter visit on the way home."}]}');
INSERT INTO feedback (feedback_id, trip_id, family_id, rating, comments) VALUES
  (1, 1, 1, 5, 'The Academy of Sciences covered a rainy morning and both kids stayed engaged.'),
  (2, 2, 1, 5, 'Zoo at opening was the right call. Balboa Park is a free afternoon on its own.'),
  (3, 3, 2, 4, 'Space Center is excellent but budget a full day and book the tram in advance.'),
  (4, 4, 2, 5, 'The DoSeum is the best children''s museum we have been to in Texas.'),
  (5, 5, 3, 5, 'Four museum days in a row worked because each one had a different feel.'),
  (6, 6, 3, 4, 'Letchworth was the surprise of the trip. Niagara itself is crowded and wet.'),
  (7, 7, 4, 4, 'Aquarium splash pad is the reason to go in May. MOSI skewed a bit old for us.'),
  (8, 8, 4, 5, 'Glass-bottom boat was perfect with a five-year-old. Everglades boardwalk was easy.'),
  (9, 9, 5, 5, 'Rim Trail plus shuttles meant no one had to be carried. Great first canyon trip.'),
  (10, 10, 5, 5, 'Desert Museum is a zoo, garden and hike in one. Do the free flight show.'),
  (11, 11, 6, 5, 'Shedd and MSI back to back is a lot; the botanic garden day balanced it out.'),
  (12, 12, 6, 3, 'Fine for a snowed-in weekend but the aquarium is small for the price.'),
  (13, 13, 7, 5, 'Georgia Aquarium is worth the ticket. Puppetry Arts workshop sold out fast.'),
  (14, 14, 7, 4, 'Off-season Tybee was calm and cheap. Bring your own beach gear.'),
  (15, 15, 8, 5, 'COSI''s toddler area let both kids play at their own level.'),
  (16, 16, 8, 4, 'Beautiful trails, but the stairs at Old Man''s Cave are not stroller friendly.'),
  (17, 17, 9, 5, 'Free Lincoln Park Zoo after the nature museum made for a cheap perfect day.'),
  (18, 18, 10, 5, 'Dark skies at Big Bend were the whole point and they delivered.'),
  (19, 19, 11, 4, 'Small zoo, small price, right size for a preschooler.'),
  (20, 20, 12, 5, 'Two days at The Strong and we still did not see everything.');
